fn totals(orders: Vec<(String, u32, f64)>) -> Vec<(String, f64)> {
    let mut res = Vec::new();
    for o in orders.iter() {
        let mut found = false;
        for r in res.iter_mut() {
            let r: &mut (String, f64) = r;
            if r.0 == o.0 { r.1 += o.1 as f64 * o.2; found = true; }
        }
        if !found { res.push((o.0.clone(), o.1 as f64 * o.2)); }
    }
    res
