import re

_UNITS = {'h': 60, 'm': 60, 's': 1}

def parse_duration(s: str) -> int:
    total = 0
    for num, unit in re.findall(r'(\d+)([hms])', s):
        total += int(num) * _UNITS[unit]
    return total
